def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, tuple[int, bool]] = {}
    history: list[list[tuple[str, tuple[int, bool] | None]]] = []
    rejected: list[int] = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token: str) -> int | None:
        if not token or any(c < "0" or c > "9" for c in token):
            return None

        # Small chunks also support amounts exceeding Python's int-string limit.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if verb not in arities or len(parts) != arities[verb]:
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        name = parts[1]
        state = accounts.get(name)

        if verb in ("freeze", "unfreeze"):
            target_frozen = verb == "freeze"
            if state is None or state[1] == target_frozen:
                rejected.append(index)
                continue
            updates = {name: (state[0], target_frozen)}
        else:
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

            if verb == "open":
                if state is not None:
                    rejected.append(index)
                    continue
                updates = {name: (amount, False)}

            elif verb == "deposit":
                if state is None:
                    rejected.append(index)
                    continue
                updates = {name: (state[0] + amount, state[1])}

            elif verb == "withdraw":
                if state is None or state[1] or state[0] < amount:
                    rejected.append(index)
                    continue
                updates = {name: (state[0] - amount, False)}

            else:  # transfer
                destination = parts[2]
                destination_state = accounts.get(destination)
                if (
                    name == destination
                    or state is None
                    or destination_state is None
                    or state[1]
                    or state[0] < amount
                ):
                    rejected.append(index)
                    continue
                updates = {
                    name: (state[0] - amount, False),
                    destination: (
                        destination_state[0] + amount,
                        destination_state[1],
                    ),
                }

        history.append([(key, accounts.get(key)) for key in updates])
        accounts.update(updates)

    return {name: state[0] for name, state in accounts.items()}, rejected
